-- 0001（PostgreSQL 方言）：demo 业务表 users + 真实用户体系 sys_* 五表。
-- 差异要点：自增用 GENERATED BY DEFAULT AS IDENTITY；时间用 TIMESTAMPTZ；enabled 用 SMALLINT(0/1)；
-- PostgreSQL 支持列级 REFERENCES ... ON DELETE CASCADE，无需单独 CONSTRAINT。

CREATE TABLE IF NOT EXISTS users (
	id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	name  TEXT NOT NULL UNIQUE,
	email TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS sys_users (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username             TEXT        NOT NULL UNIQUE,
    password_hash        TEXT        NOT NULL,
    email                TEXT,
    enabled              SMALLINT    NOT NULL DEFAULT 1,
    password_changed_at  TIMESTAMPTZ NULL,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS sys_roles (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    description TEXT
);

CREATE TABLE IF NOT EXISTS sys_permissions (
    id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS sys_user_roles (
    user_id BIGINT NOT NULL REFERENCES sys_users (id) ON DELETE CASCADE,
    role_id BIGINT NOT NULL REFERENCES sys_roles (id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, role_id)
);

CREATE TABLE IF NOT EXISTS sys_role_permissions (
    role_id       BIGINT NOT NULL REFERENCES sys_roles (id) ON DELETE CASCADE,
    permission_id BIGINT NOT NULL REFERENCES sys_permissions (id) ON DELETE CASCADE,
    PRIMARY KEY (role_id, permission_id)
);
